-- TASK-0065 Open Hand teaching items: biology (15 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'biology';
  v_tsv uuid := 'c676d1fc-3b58-4896-89e3-852d9bd1f81b';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"APBIO-OHT-1.2","topic_code":"1.2","title":"Elements of Life","stem":"A chemical analysis of an unknown biological polymer finds carbon, hydrogen, oxygen, nitrogen, and phosphorus, but no sulfur. Which molecule is most consistent with this composition?","choices":[{"choice_key":"A","choice_text":"A protein with many cysteine residues, because proteins contain nitrogen and sulfur.","is_correct":false,"rationale":"Tempting because proteins do contain N and some S. But this sample has phosphorus and no sulfur, and proteins do not have phosphate in their backbone. Fix: when an analysis shows both N and P but no S, choose a nucleic acid over a protein."},{"choice_key":"B","choice_text":"A triglyceride, because fats are rich in carbon and hydrogen and store energy.","is_correct":false,"rationale":"Tempting because C, H and O dominate fats. But a triglyceride has no nitrogen or phosphorus. Fix: check for N and P before you choose a lipid; triglycerides contain only C, H and O."},{"choice_key":"C","choice_text":"A cellulose chain, because it is a large polymer built from many repeating subunits and its monomers are joined into long chains by covalent bonds.","is_correct":false,"rationale":"Tempting because cellulose is a polymer. But carbohydrates contain only C, H and O, so N and P rule it out. Fix: list the elements each molecule class contains and match them to the analysis; cellulose has only C, H and O."},{"choice_key":"D","choice_text":"A DNA strand, because nitrogen is in its nucleotide bases and phosphorus is in the phosphate groups of its backbone.","is_correct":true,"rationale":"Nucleotides contain nitrogen in their bases and phosphorus in the sugar-phosphate backbone, and DNA has no sulfur. That combination of N and P without S points to a nucleic acid."}]},{"content_key":"APBIO-OHT-1.3","topic_code":"1.3","title":"Introduction to Macromolecules","stem":"A cell links 50 amino acids into one polypeptide chain by forming peptide bonds. Which statement correctly describes the water involved?","choices":[{"choice_key":"A","choice_text":"Forty-nine water molecules are released, one for each peptide bond formed by dehydration synthesis.","is_correct":true,"rationale":"Joining 50 monomers in a chain forms 49 bonds, and each dehydration synthesis reaction removes one water molecule. So 49 waters are released."},{"choice_key":"B","choice_text":"Fifty water molecules are released, one for each amino acid added.","is_correct":false,"rationale":"Tempting if you count monomers instead of bonds. But a chain of 50 has only 49 links between subunits. Fix: water released equals bonds formed, which is monomers minus one."},{"choice_key":"C","choice_text":"Forty-nine water molecules are consumed, because building a polymer requires adding water.","is_correct":false,"rationale":"Tempting if you mix up the two reactions. Adding water is hydrolysis, which breaks polymers. Fix: dehydration synthesis removes water as it builds; hydrolysis adds water as it breaks."},{"choice_key":"D","choice_text":"No water is involved, because peptide bonds form by simply joining two monomers directly, which makes dehydration synthesis seem to be a simple joining reaction.","is_correct":false,"rationale":"Tempting because the bond seems to just connect two molecules. But each covalent bond formed between monomers releases an H and an OH as water. Fix: remember 'dehydration' means water is removed."}]},{"content_key":"APBIO-OHT-1.5","topic_code":"1.5","title":"Lipids","stem":"A scientist compares two fats at 4 degrees C. Every fatty acid in Fat 1 has only single carbon-carbon bonds. Every fatty acid in Fat 2 has two carbon-carbon double bonds. Which prediction is best supported by the structure of the fatty acids?","choices":[{"choice_key":"A","choice_text":"Fat 2 is more likely to be solid, because double bonds are stronger and hold the molecules together.","is_correct":false,"rationale":"Tempting because double bonds sound more rigid. But the key effect is the kink they put in the chain, which prevents tight packing. Fix: ask how the shape of the chain affects packing."},{"choice_key":"B","choice_text":"Fat 1 is more likely to be solid, because its straight chains pack tightly together.","is_correct":true,"rationale":"Saturated chains have only single bonds and stay straight, so they pack closely and the fat is solid at lower temperatures. The double bonds in Fat 2 introduce kinks that keep it loosely packed."},{"choice_key":"C","choice_text":"Both fats are equally likely to be solid, because both are made of carbon and hydrogen.","is_correct":false,"rationale":"Tempting because both are lipids with similar elements. But identical elements do not mean identical shape; saturation changes packing and melting behavior. Fix: compare single versus double bonds, not just composition."},{"choice_key":"D","choice_text":"Fat 2 is more likely to be solid, because it has more hydrogen atoms bonded to its carbons.","is_correct":false,"rationale":"Tempting if you reverse saturation. But a double bond means fewer hydrogens, and Fat 2 is the unsaturated one. Fix: count the double bonds in each chain, and predict that the fat with none (more hydrogen, straight chains) packs into a solid."}]},{"content_key":"APBIO-OHT-1.6","topic_code":"1.6","title":"Nucleic Acids","stem":"One strand of a DNA segment is written 5'-ATGCCG-3'. Which is the sequence of the complementary DNA strand, written 5' to 3'?","choices":[{"choice_key":"A","choice_text":"5'-TACGGC-3'","is_correct":false,"rationale":"Tempting if you pair the bases correctly but write them in the same left-to-right order. But the strands run antiparallel, so that reads 3' to 5'. Fix: reverse the complement to read 5' to 3'."},{"choice_key":"B","choice_text":"5'-UACGGC-3'","is_correct":false,"rationale":"Tempting if you swap in uracil as the partner for adenine. But U pairs with A only in RNA, and this is a DNA strand, which uses thymine. Fix: pair A with T, never U, when you write a DNA strand."},{"choice_key":"C","choice_text":"5'-GCCGTA-3'","is_correct":false,"rationale":"Tempting if you only reverse the original strand. But reversing does not substitute complementary bases. Fix: both complement each base and reverse the direction."},{"choice_key":"D","choice_text":"5'-CGGCAT-3'","is_correct":true,"rationale":"Pairing A-T and C-G gives 3'-TACGGC-5', because the strands are antiparallel. Reading that strand in its own 5' to 3' direction gives 5'-CGGCAT-3'."}]},{"content_key":"APBIO-OHT-2.1","topic_code":"2.1","title":"Cell Structure and Function","stem":"A white blood cell engulfs a bacterium into a vesicle and destroys it. Which organelle most directly carries out the destruction of the engulfed material?","choices":[{"choice_key":"A","choice_text":"Smooth ER, because it detoxifies harmful substances in the cell and keeps the cell safe from toxins that enter.","is_correct":false,"rationale":"Tempting because destroying a bacterium sounds like detoxification. But smooth ER handles lipid synthesis and detoxification of chemicals, not digestion of engulfed cells. Fix: match digestion to lysosomes."},{"choice_key":"B","choice_text":"Rough ER, because its ribosomes make proteins that attack the bacterium.","is_correct":false,"rationale":"Tempting because enzymes are proteins and rough ER makes proteins. But the ER builds proteins; it does not digest the vesicle's contents. Fix: separate making proteins from breaking down material."},{"choice_key":"C","choice_text":"Lysosome, because it fuses with the vesicle and its hydrolytic enzymes digest the contents.","is_correct":true,"rationale":"Lysosomes contain hydrolytic enzymes that digest material. Their structure, an enclosed compartment of digestive enzymes, lets them break down the bacterium without harming the rest of the cell."},{"choice_key":"D","choice_text":"Mitochondrion, because it supplies the large amount of ATP needed for the response.","is_correct":false,"rationale":"Tempting because every cell activity needs energy. But the question asks which organelle destroys the material, and mitochondria make ATP rather than digest. Fix: ask what the structure does, not what powers it."}]},{"content_key":"APBIO-OHT-2.2","topic_code":"2.2","title":"Cell Size","stem":"Two cube-shaped cells are compared. Cell P has sides of 2 micrometers and Cell Q has sides of 4 micrometers. Which statement correctly compares their surface area-to-volume ratios?","choices":[{"choice_key":"A","choice_text":"Both surface area and volume double, so the ratio is the same in both cells.","is_correct":false,"rationale":"Tempting if you assume everything scales with length. But area scales with the square and volume with the cube of side length. Fix: square for area, cube for volume."},{"choice_key":"B","choice_text":"Cell Q's surface area is 4 times greater and its volume is 8 times greater, so its ratio is half that of Cell P.","is_correct":true,"rationale":"Doubling the side length multiplies surface area by 4 (24 to 96) and volume by 8 (8 to 64). The ratio falls from 3 to 1.5, so Cell Q has less membrane per unit of volume for exchange."},{"choice_key":"C","choice_text":"Cell Q's surface area is 8 times greater and its volume is 4 times greater, so its ratio is twice that of Cell P.","is_correct":false,"rationale":"Tempting if you swap the exponents. But surface area is a squared quantity and volume is a cubed quantity. Fix: area goes with 2, volume with 3."},{"choice_key":"D","choice_text":"Cell Q's surface area increases 4-fold and volume 8-fold, so its ratio is higher because 8 is greater than 4.","is_correct":false,"rationale":"Tempting if you read the larger number as the ratio. But surface area-to-volume is surface area divided by volume, 4 over 8, which is smaller. Fix: put surface area on top and volume on the bottom."}]},{"content_key":"APBIO-OHT-2.3","topic_code":"2.3","title":"Plasma Membrane","stem":"Phospholipids are placed in water and spontaneously form a closed bilayer sphere. Which description of the arrangement is correct?","choices":[{"choice_key":"A","choice_text":"The hydrophobic tails face the water on both surfaces, and the heads face each other in the middle so the water-loving side stays in the middle of the bilayer.","is_correct":false,"rationale":"Tempting if you reverse the polarity of the two ends. But the phosphate head is hydrophilic, and nonpolar tails avoid water. Fix: hydrophilic toward water, hydrophobic away."},{"choice_key":"B","choice_text":"All heads and tails mix evenly throughout the sphere because the molecules move freely.","is_correct":false,"rationale":"Tempting because the membrane is fluid. But movement within the membrane does not change the orientation, which is set by hydrophilic and hydrophobic parts. Fix: molecules drift, but the head-out, tail-in order stays."},{"choice_key":"C","choice_text":"The heads of the outer layer face the tails of the inner layer so the layers stick together.","is_correct":false,"rationale":"Tempting if you think layers must attract each other. But hydrophobic tails group together to avoid water, and heads contact water on each side. Fix: tails meet tails in the center."},{"choice_key":"D","choice_text":"The hydrophilic phosphate heads face the water on both the outer and inner surfaces, and the hydrophobic fatty-acid tails face each other inside the bilayer.","is_correct":true,"rationale":"Each phospholipid is amphipathic, so its polar head faces the water and its nonpolar tails are tucked away from it. In a bilayer this puts the tails in the middle, facing each other."}]},{"content_key":"APBIO-OHT-2.4","topic_code":"2.4","title":"Membrane Permeability","stem":"A cell is in a solution containing equal amounts of four substances, and no transport proteins for any of them are present in the membrane. Which substance would cross the phospholipid bilayer most readily?","choices":[{"choice_key":"A","choice_text":"N2, because it is small and nonpolar and can dissolve in the hydrophobic interior of the bilayer.","is_correct":true,"rationale":"Small nonpolar molecules such as N2, O2 and CO2 pass freely through the hydrophobic tail region. Without transport proteins, nothing else listed crosses as readily."},{"choice_key":"B","choice_text":"Na+, because it is a very small ion.","is_correct":false,"rationale":"Tempting if you only consider size. But a charged particle is blocked by the hydrophobic tails regardless of size. Fix: check polarity and charge, not just size."},{"choice_key":"C","choice_text":"Glucose, because the cell constantly needs it for energy and the cell would take it in as quickly as it needs.","is_correct":false,"rationale":"Tempting because need seems to explain movement. But crossing depends on a molecule's properties, and glucose is large and polar, so it requires a transport protein. Fix: properties, not need, determine passage."},{"choice_key":"D","choice_text":"K+, because it is moving toward a region of the cell where potassium is abundant.","is_correct":false,"rationale":"Tempting if you assume direction decides crossing. But K+ is charged and cannot dissolve in the tails, so it needs a channel in any direction. Fix: charged substances need proteins."}]},{"content_key":"APBIO-OHT-2.5","topic_code":"2.5","title":"Membrane Transport","stem":"The concentration of an ion is 140 mM inside a cell and 4 mM outside. A membrane protein moves the ion into the cell. Which statement best describes this movement?","choices":[{"choice_key":"A","choice_text":"It is passive transport, because a membrane protein is involved and proteins lower the energy needed.","is_correct":false,"rationale":"Tempting if you assume any protein makes transport passive. But direction matters: moving up a gradient costs energy no matter which protein helps. Fix: first find the gradient direction."},{"choice_key":"B","choice_text":"It is facilitated diffusion, because ions are charged and charged particles always use channels.","is_correct":false,"rationale":"Tempting because charged ions do need proteins to cross. But facilitated diffusion only moves substances down their gradient, and here the ion moves up it. Fix: channels explain how, gradient direction explains energy."},{"choice_key":"C","choice_text":"It is active transport, because the ion moves from low to high concentration, which requires energy input, typically from ATP.","is_correct":true,"rationale":"Net movement against the concentration gradient is active transport. The cell must supply energy, usually ATP, to move the ion toward the side where it is already more concentrated."},{"choice_key":"D","choice_text":"It is endocytosis, because transport against a gradient is always done in vesicles.","is_correct":false,"rationale":"Tempting because endocytosis also uses energy. But endocytosis moves bulk material in vesicles, and here a single protein moves one ion. Fix: pumps move individual ions against gradients; vesicles move large particles."}]},{"content_key":"APBIO-OHT-2.6","topic_code":"2.6","title":"Facilitated Diffusion","stem":"Sodium ion concentration is 145 mM outside a neuron and 12 mM inside. Sodium channels in the membrane open. Which statement correctly describes what happens?","choices":[{"choice_key":"A","choice_text":"Sodium ions flow out of the cell, because open channels pump ions out to keep the inside low.","is_correct":false,"rationale":"Tempting if you picture the channel as a pump. But a channel only provides a path, and ions follow the gradient, which here points inward. Fix: find the side with the higher concentration and predict flow through the open channel toward the lower side."},{"choice_key":"B","choice_text":"Sodium ions flow into the cell through the channels down their concentration gradient, with no direct ATP use.","is_correct":true,"rationale":"Open channels give a path through the hydrophobic bilayer, and the gradient provides the driving force. Because this is facilitated diffusion, movement is from high to low and needs no ATP."},{"choice_key":"C","choice_text":"Sodium ions flow in, but only because ATP is used to power the channel, since a protein is involved.","is_correct":false,"rationale":"Tempting if you call any protein-assisted movement active transport. But a channel does not use ATP; diffusion down the gradient supplies the energy. Fix: decide active or passive from the gradient direction, not from whether a protein is involved."},{"choice_key":"D","choice_text":"Sodium ions cannot cross at all, because charged ions are blocked by the membrane.","is_correct":false,"rationale":"Tempting because the bilayer blocks charged ions on its own. But channel proteins provide a route for specific ions. Fix: when an ion crosses a membrane, look for the channel or carrier protein that lets it through."}]},{"content_key":"APBIO-OHT-2.8","topic_code":"2.8","title":"Mechanisms of Transport","stem":"A poison stops a nerve cell's ATP production but does not damage its membrane proteins. Which is the most direct consequence for the cell's Na+/K+ pumps and ion gradients?","choices":[{"choice_key":"A","choice_text":"Nothing changes, because ion movement across membranes is entirely passive because pumps are not needed to hold ions at different levels across a membrane.","is_correct":false,"rationale":"Tempting because much ion movement is passive. But maintaining the gradients requires active transport by the pump, which depends on ATP. Fix: passive movement uses gradients, active transport builds them."},{"choice_key":"B","choice_text":"The pumps keep working at the same rate, because the proteins themselves are undamaged.","is_correct":false,"rationale":"Tempting because the poison leaves the proteins intact. But the pump needs ATP to operate, not just an intact structure. Fix: an undamaged pump still needs its energy supply."},{"choice_key":"C","choice_text":"The pumps reverse direction and move Na+ in and K+ out by facilitated diffusion.","is_correct":false,"rationale":"Tempting because ions would move down their gradients without ATP. But the pumps do not reverse; they simply stop, and any leaking happens through other pathways. Fix: no ATP means the pump halts."},{"choice_key":"D","choice_text":"The pumps stop moving Na+ out and K+ in against their gradients, so the gradients and membrane potential gradually dissipate.","is_correct":true,"rationale":"The Na+/K+ pump is an ATPase that needs a steady supply of ATP to move ions against their gradients. Without ATP the pump fails, and the gradients and membrane potential it maintains cannot be sustained."}]},{"content_key":"APBIO-OHT-2.10","topic_code":"2.10","title":"Origins of Cell Compartmentalization","stem":"Which observation most directly supports the hypothesis that mitochondria descended from free-living bacteria, rather than having always been made entirely from the host cell's own genes?","choices":[{"choice_key":"A","choice_text":"Mitochondria produce ATP, which prokaryotes also produce.","is_correct":false,"rationale":"Tempting because both make ATP. But shared function does not show common origin, since many structures share functions. Fix: look for structural or genetic evidence of ancestry."},{"choice_key":"B","choice_text":"Mitochondria are enclosed by membranes, like the nucleus and other organelles and so they must have originated as separate organisms from the host.","is_correct":false,"rationale":"Tempting because membranes appear in the theory. But all eukaryotic organelles have membranes, so this does not single out mitochondria. Fix: pick evidence unique to a prokaryote, such as its own DNA."},{"choice_key":"C","choice_text":"Mitochondria contain their own circular DNA and ribosomes that resemble those of bacteria, and they divide in a way similar to binary fission.","is_correct":true,"rationale":"Bacterial-like genetic material, ribosomes and division are evidence of a prokaryotic ancestry for the organelle. These are features expected if mitochondria began as separate organisms."},{"choice_key":"D","choice_text":"Mitochondria are found in almost every eukaryotic cell, which shows they are very ancient.","is_correct":false,"rationale":"Tempting because widespread features seem old. But being common does not show origin as a separate organism. Fix: the evidence must show prokaryote-like traits."}]},{"content_key":"APBIO-OHT-3.1","topic_code":"3.1","title":"Enzymes","stem":"An uncatalyzed reaction has an activation energy of 75 kJ/mol and releases 30 kJ/mol overall. An enzyme lowers the activation energy to 40 kJ/mol. What does the enzyme change?","choices":[{"choice_key":"A","choice_text":"It supplies 35 kJ/mol of energy to the substrate so the reaction can start and then the substrate has enough energy to react without help.","is_correct":false,"rationale":"Tempting because 75 minus 40 is 35 and it looks like a donated amount. But enzymes do not add energy; they provide an easier path. Fix: describe the enzyme as lowering the barrier from 75 to 40 kJ/mol, never as adding energy."},{"choice_key":"B","choice_text":"It lowers the energy barrier to 40 kJ/mol, and the reaction still releases 30 kJ/mol overall.","is_correct":true,"rationale":"Enzymes speed reactions by lowering activation energy, not by changing the reactants' or products' energy. The reaction therefore reaches the same overall 30 kJ/mol release, only faster."},{"choice_key":"C","choice_text":"It makes the reaction release 65 kJ/mol overall, because the barrier is 35 kJ/mol lower.","is_correct":false,"rationale":"Tempting if you add the barrier reduction to the energy released. But the overall energy change depends only on reactants and products. Fix: keep the energy released (30 kJ/mol) separate from the activation energy, the only value the enzyme changes."},{"choice_key":"D","choice_text":"It is used up in the reaction as it permanently joins the substrate.","is_correct":false,"rationale":"Tempting because the enzyme binds the substrate. But the enzyme is released unchanged after catalysis and can be reused. Fix: describe enzyme binding as temporary, with the enzyme unchanged and reusable after the reaction."}]},{"content_key":"APBIO-OHT-3.4","topic_code":"3.4","title":"Photosynthesis","stem":"Light strikes the thylakoid membranes of a chloroplast. Which pair of products of the light reactions is used in the stroma to build sugar?","choices":[{"choice_key":"A","choice_text":"Oxygen and glucose","is_correct":false,"rationale":"Tempting because these are the best-known photosynthesis products. But oxygen comes from splitting water and is released, and glucose is made in the Calvin cycle, not the light reactions. Fix: list what the light reactions make, then pick the products the Calvin cycle uses in the stroma."},{"choice_key":"B","choice_text":"Carbon dioxide and water","is_correct":false,"rationale":"Tempting because both are involved in photosynthesis. But they are inputs, not products of the light reactions. Fix: sort each molecule into input or product before you answer; water and CO2 are inputs."},{"choice_key":"C","choice_text":"ATP and NADPH","is_correct":true,"rationale":"The light reactions use light energy and electron transport to produce ATP (by chemiosmosis) and NADPH. The Calvin cycle in the stroma uses both to build sugar from carbon dioxide."},{"choice_key":"D","choice_text":"NADH and FADH2","is_correct":false,"rationale":"Tempting because these are electron carriers. But NADH and FADH2 are produced in cellular respiration. Fix: look for NADPH in photosynthesis, and save NADH and FADH2 for cellular respiration."}]},{"content_key":"APBIO-OHT-3.5","topic_code":"3.5","title":"Cellular Respiration","stem":"When oxygen is removed from isolated mitochondria that are supplied with NADH, ATP production by ATP synthase quickly falls. Which statement best explains this result?","choices":[{"choice_key":"A","choice_text":"Oxygen binds directly to ADP and phosphate to form ATP.","is_correct":false,"rationale":"Tempting because oxygen is linked with energy release. But oxygen does not make ATP directly; ATP synthase does. Fix: trace oxygen to the end of the electron transport chain, where it accepts electrons, not to ATP synthase."},{"choice_key":"B","choice_text":"Oxygen is required to split glucose during glycolysis in the mitochondria in order to feed the later steps.","is_correct":false,"rationale":"Tempting because oxygen is called a respiration requirement. But glycolysis occurs in the cytosol and does not need oxygen. Fix: place glycolysis in the cytosol, where it runs without oxygen, before you link oxygen to ATP production."},{"choice_key":"C","choice_text":"Oxygen supplies the protons that are pumped across the inner mitochondrial membrane.","is_correct":false,"rationale":"Tempting because the gradient is made of protons. But the pumped protons come from the matrix side, and oxygen instead accepts electrons. Fix: give oxygen the job of accepting electrons at the end of the chain, and look elsewhere for the pumped protons."},{"choice_key":"D","choice_text":"Oxygen is the final electron acceptor, so without it electron flow stops and the proton gradient used by ATP synthase is no longer maintained.","is_correct":true,"rationale":"Electrons from NADH pass along the electron transport chain to oxygen, which forms water. Without oxygen the chain backs up, protons are no longer pumped, and chemiosmosis cannot drive ATP synthase."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
